import {
  mkdir,
  mkdtemp,
  readFile,
  writeFile,
  access,
  chmod,
} from "node:fs/promises";
import { join } from "node:path";
import {
  createAcpRuntime,
  createAgentRegistry,
  createFileSessionStore,
} from "/tmp/agx-decision-0E6raB/acpx-package/dist/runtime.js";
import { modelServer } from "./model-server.ts";
import { runClaude } from "/home/fuyu/dotfiles/tools/agx-worker/src/workers/run-claude.ts";
import { runAcpxWorker } from "./acpx-worker-candidate.ts";

async function main() {
  const vendor = process.env.AGX_AUDIT_VENDOR === "claude" ? "claude" : "codex";
  const transport = process.env.AGX_AUDIT_TRANSPORT ?? "acpx";
  const scenario = process.env.AGX_AUDIT_SCENARIO ?? "normal";
  // Native Claude sandbox bridge sockets must fit the Unix-domain path limit.
  const root = await mkdtemp("/tmp/agx-native-");
  const cwd = join(root, "workspace");
  const vendorHome = join(root, "vendor-home");
  const temp = join(root, "tmp");
  await mkdir(cwd, { recursive: true });
  await mkdir(vendorHome, { recursive: true });
  await mkdir(temp, { recursive: true });
  const outsideRoot = await mkdtemp("/home/fuyu/dotfiles/.agx-native-audit-");
  const marker =
    scenario === "sandbox"
      ? join(outsideRoot, "outside-marker")
      : join(cwd, "inside-marker");
  const command = `${scenario === "hook-deny" ? "# audit-hook-denied\n" : ""}printf audit > '${marker}'`;
  const api = modelServer({
    vendor,
    scenario,
    command,
    logPath: join(root, "http.jsonl"),
  });
  const hookLog = join(root, "hooks.jsonl");
  const hook = {
    type: "command",
    command: `${process.execPath} ${join(import.meta.dir, "hook.ts")}`,
    timeout: 5,
  };
  const hooks = Object.fromEntries(
    [
      "SessionStart",
      "UserPromptSubmit",
      "PreToolUse",
      "PostToolUse",
      "Stop",
    ].map((event) => [event, [{ hooks: [hook] }]]),
  );
  const provider = {
    name: "audit",
    base_url: `${api.url}/v1`,
    wire_api: "responses",
    requires_openai_auth: false,
    supports_websockets: false,
    request_max_retries: 0,
    stream_max_retries: 0,
    stream_idle_timeout_ms: 1000,
  };
  const codexConfig = {
    model: "gpt-6.1-sol",
    model_provider: "audit",
    model_providers: { audit: provider },
    features: { hooks: true },
    approval_policy: "never",
    sandbox_mode: scenario === "read-only" ? "read-only" : "workspace-write",
    "sandbox_workspace_write.exclude_slash_tmp": true,
    "sandbox_workspace_write.exclude_tmpdir_env_var": true,
  };
  const codexShim = join(root, "codex-audit");
  await writeFile(
    codexShim,
    '#!/bin/sh\n# shim: exec-wrapper — vetted audit hooks only; all other argv is forwarded.\nexec /home/linuxbrew/.linuxbrew/bin/codex --dangerously-bypass-hook-trust "$@"\n',
  );
  await chmod(codexShim, 0o755);
  if (vendor === "codex") {
    await writeFile(join(vendorHome, "hooks.json"), JSON.stringify({ hooks }));
    await writeFile(
      join(vendorHome, "config.toml"),
      `model = "gpt-6.1-sol"\nmodel_provider = "audit"\napproval_policy = "never"\n[model_providers.audit]\nname = "audit"\nbase_url = "${api.url}/v1"\nwire_api = "responses"\nrequires_openai_auth = false\nsupports_websockets = false\nrequest_max_retries = 0\nstream_max_retries = 0\nstream_idle_timeout_ms = 1000\n[features]\nhooks = true\n`,
    );
  } else {
    await writeFile(
      join(vendorHome, "settings.json"),
      JSON.stringify({
        hooks,
        sandbox: {
          enabled: true,
          autoAllowBashIfSandboxed: true,
          allowUnsandboxedCommands: false,
          failIfUnavailable: true,
        },
        permissions: {
          defaultMode: scenario === "read-only" ? "plan" : "acceptEdits",
        },
      }),
    );
  }
  const env = {
    TMPDIR: temp,
    TMP: temp,
    TEMP: temp,
    AGX_AUDIT_HOOK_LOG: hookLog,
    CODEX_PATH:
      process.env.AGX_AUDIT_PATCH_HOOK_SOURCE === undefined
        ? codexShim
        : join(import.meta.dir, "codex-appserver-shim.ts"),
    CODEX_HOME: vendorHome,
    CODEX_CONFIG: JSON.stringify(codexConfig),
    MODEL_PROVIDER: "audit",
    ...(process.env.AGX_AUDIT_PATCH_HOOK_SOURCE === undefined
      ? {}
      : {
          AGX_AUDIT_PATCH_HOOK_SOURCE: process.env.AGX_AUDIT_PATCH_HOOK_SOURCE,
        }),
    ...(process.env.AGX_AUDIT_TRUST_HOOKS === undefined
      ? {}
      : { AGX_AUDIT_TRUST_HOOKS: process.env.AGX_AUDIT_TRUST_HOOKS }),
    CLAUDE_CONFIG_DIR: vendorHome,
    CLAUDE_CODE_EXECUTABLE: "/home/fuyu/.local/bin/claude",
    ACPX_CLAUDE_INCLUDE_USER_SETTINGS: "1",
    ANTHROPIC_BASE_URL: api.url,
    ANTHROPIC_API_KEY: "audit-not-a-real-key",
    ANTHROPIC_AUTH_TOKEN: "",
    CLAUDE_CODE_OAUTH_TOKEN: "",
    OPENAI_API_KEY: "audit-not-a-real-key",
    CODEX_API_KEY: "audit-not-a-real-key",
    CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC: "1",
    DISABLE_TELEMETRY: "1",
    DISABLE_AUTOUPDATER: "1",
    MAX_RETRIES: "0",
  };
  const adapter = process.env.AGX_AUDIT_ADAPTER_DIR ?? vendor;
  const runtime = createAcpRuntime({
    cwd,
    sessionStore: createFileSessionStore({ stateDir: join(root, "state") }),
    agentRegistry: createAgentRegistry({
      overrides: {
        [vendor]: [
          join(import.meta.dir, "node/bin/node"),
          join(import.meta.dir, adapter, "dist/index.js"),
        ],
      },
    }),
    agentProcessEnv: env,
    permissionMode: "deny-all",
    fs: false,
    terminal: false,
    timeoutMs: 15000,
    verbose: false,
  });
  const events: unknown[] = [];
  const start = performance.now();
  let failure: string | undefined;
  try {
    if (transport === "agx") {
      const envFile = join(root, "native-env.json");
      await writeFile(envFile, JSON.stringify(env));
      const launcher = join(import.meta.dir, "vendor-launcher.ts");
      if (vendor === "claude") {
        process.env.AGX_AUDIT_NATIVE_ENV_FILE = envFile;
        const receipt = await runClaude({
          target: cwd,
          prompt: "Perform the scoped audit task; reply AUDIT_COMPLETED.",
          model: "claude-sonnet-4-6",
          permissionMode: scenario === "read-only" ? "plan" : "acceptEdits",
          maxTurns: 3,
          timeoutMs: 15000,
          maxBudgetUsd: 2,
          safeMode: false,
          bare: false,
          progressFile: join(root, "progress.jsonl"),
          persistSession: true,
          claudeBin: launcher,
        });
        await writeFile(join(root, "native.stdout"), receipt.stdout);
        await writeFile(join(root, "native.stderr"), receipt.stderr);
        events.push({
          type: "agx_receipt",
          exit: receipt.exitCode,
          capacityCause: receipt.capacityCause,
          timedOut: receipt.timedOut,
        });
      } else {
        const prompt = join(root, "prompt.txt");
        await writeFile(
          prompt,
          "Perform the scoped audit task; reply AUDIT_COMPLETED.",
        );
        const args = [
          process.execPath,
          "/home/fuyu/dotfiles/tools/agx-worker/src/workers/codex.ts",
          "--model",
          "gpt-6.1-sol",
          "--effort",
          "high",
          "--sandbox",
          scenario === "read-only" ? "read-only" : "workspace-write",
          "--cd",
          cwd,
          "--prompt-file",
          prompt,
          "--receipt-dir",
          join(root, "receipts"),
          "--timeout-s",
          "15",
        ];
        const proc = Bun.spawn(args, {
          env: {
            ...process.env,
            AGX_CODEX_BIN: launcher,
            AGX_CODEX_HOST_FILE: join(root, "absent-host.toml"),
            AGX_AUDIT_NATIVE_ENV_FILE: envFile,
          },
          stdin: "ignore",
          stdout: "pipe",
          stderr: "pipe",
          timeout: 20000,
        });
        const [out, err, exit] = await Promise.all([
          proc.stdout.text(),
          proc.stderr.text(),
          proc.exited,
        ]);
        await writeFile(join(root, "native.stdout"), out);
        await writeFile(join(root, "native.stderr"), err);
        events.push(
          ...out
            .trim()
            .split("\n")
            .filter(Boolean)
            .map((line) => {
              try {
                return { ...JSON.parse(line), agx_process_exit: exit };
              } catch {
                return { raw: line, agx_process_exit: exit };
              }
            }),
        );
        if (exit !== 0 && !out.includes('"capacity"'))
          failure = `agx exit=${exit}: ${err.slice(-1000)}`;
      }
    } else if (transport === "native") {
      const cmd =
        vendor === "codex"
          ? [
              codexShim,
              "exec",
              "--json",
              "--skip-git-repo-check",
              "--sandbox",
              scenario === "read-only" ? "read-only" : "workspace-write",
              "-C",
              cwd,
              "-m",
              "gpt-6.1-sol",
              "-c",
              'approval_policy="never"',
              "Perform the scoped audit task; reply AUDIT_COMPLETED.",
            ]
          : [
              "/home/fuyu/.local/bin/claude",
              "-p",
              "Perform the scoped audit task; reply AUDIT_COMPLETED.",
              "--model",
              "claude-sonnet-4-6",
              "--permission-mode",
              scenario === "read-only" ? "plan" : "acceptEdits",
              "--output-format",
              "stream-json",
              "--verbose",
              "--max-turns",
              "3",
            ];
      const proc = Bun.spawn(cmd, {
        cwd,
        env: { ...process.env, ...env },
        stdin: "ignore",
        stdout: "pipe",
        stderr: "pipe",
        timeout: 15000,
      });
      const [out, err, exit] = await Promise.all([
        proc.stdout.text(),
        proc.stderr.text(),
        proc.exited,
      ]);
      await writeFile(join(root, "native.stdout"), out);
      await writeFile(join(root, "native.stderr"), err);
      events.push(
        ...out
          .trim()
          .split("\n")
          .filter(Boolean)
          .map((line) => {
            try {
              return JSON.parse(line);
            } catch {
              return { raw: line };
            }
          }),
      );
      if (exit !== 0)
        failure = `native exit=${exit} signal=${proc.signalCode}: ${err.slice(-1500)}`;
    } else if (transport === "nodebridge") {
      const inputFile = join(root, "node-input.json");
      await writeFile(inputFile, JSON.stringify({ root, cwd, vendor, adapter, scenario, env }));
      const proc = Bun.spawn([join(import.meta.dir, "node/bin/node"), join(import.meta.dir, "node-client.ts")], { cwd, env: { ...process.env, AGX_AUDIT_NODE_INPUT: inputFile }, stdin: "ignore", stdout: "pipe", stderr: "pipe", timeout: 25000 });
      const [out, err, exit] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited]);
      await writeFile(join(root, "node.stderr"), err);
      if (exit !== 0) throw Error(`native Node bridge ${exit}: ${err.slice(-2000)}`);
      const parsed = JSON.parse(out.trim().split("\n").at(-1)!);
      events.push(...parsed.events);
    } else if (transport === "bridge") {
      const receipt = await runAcpxWorker({
        runtime,
        input: {
          sessionKey: `audit-${vendor}-${scenario}`,
          agent: vendor,
          mode: "persistent",
          sessionOptions: {
            model: vendor === "codex" ? "gpt-6.1-sol" : "claude-sonnet-4-6",
            maxTurns: 3,
          },
        },
        vendor,
        prompt: "Perform the scoped audit task; reply AUDIT_COMPLETED.",
        sandbox: scenario === "read-only" ? "read-only" : "workspace-write",
        timeoutMs: 15000,
        onEvent: (event) => events.push(event),
      });
      events.push({ type: "bridge_receipt", ...receipt });
    } else {
      const handle = await runtime.ensureSession({
        sessionKey: `audit-${vendor}-${scenario}`,
        agent: vendor,
        mode: "persistent",
        sessionOptions: {
          model: vendor === "codex" ? "gpt-6.1-sol" : "claude-sonnet-4-6",
          maxTurns: 3,
        },
      });
      await writeFile(
        join(root, "handle.json"),
        JSON.stringify(handle, null, 2),
      );
      if (vendor === "codex" && scenario === "read-only")
        await runtime.setMode({ handle, mode: "read-only" });
      for await (const event of runtime.runTurn({
        handle,
        text: "Perform the scoped audit task; reply AUDIT_COMPLETED.",
        mode: "prompt",
        requestId: crypto.randomUUID(),
        timeoutMs: 15000,
      }))
        events.push(event);
    }
  } catch (error) {
    failure = String(error);
  } finally {
    await runtime.shutdown();
    await api.server.stop(true);
  }
  const present = await access(marker).then(
    () => true,
    () => false,
  );
  const hookText = await readFile(hookLog, "utf8").catch(() => "");
  const result = {
    transport,
    vendor,
    adapter,
    scenario,
    root,
    outsideRoot,
    marker,
    present,
    elapsedMs: Math.round(performance.now() - start),
    ...api.counts(),
    failure,
    hooks: hookText
      .trim()
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line).hook_event_name),
    events,
  };
  await writeFile(join(root, "result.json"), JSON.stringify(result, null, 2));
  process.stdout.write(
    `${JSON.stringify({ ...result, events: events.slice(-4) })}\n`,
  );
}
main().catch((error) => {
  process.stderr.write(`FATAL: ${String(error)}\n`);
  process.exitCode = 2;
});

