import { appendFileSync } from "node:fs";

export function modelServer(options: {
  vendor: "codex" | "claude";
  scenario: string;
  command: string;
  logPath: string;
}) {
  let requests = 0;
  let modelCalls = 0;
  const sse = (events: { event: string; data: unknown }[]) =>
    new Response(
      events
        .map((e) => `event: ${e.event}\ndata: ${JSON.stringify(e.data)}\n\n`)
        .join(""),
      {
        headers: {
          "content-type": "text/event-stream",
          "cache-control": "no-cache",
        },
      },
    );
  const server = Bun.serve({
    hostname: "127.0.0.1",
    port: 0,
    async fetch(req) {
      const url = new URL(req.url);
      const raw = await req.text();
      const body = raw === "" ? {} : JSON.parse(raw);
      requests++;
      appendFileSync(
        options.logPath,
        `${JSON.stringify({ path: url.pathname, body })}\n`,
      );
      if (url.pathname.includes("count_tokens"))
        return Response.json({ input_tokens: 20 });
      if (req.method === "GET")
        return Response.json({
          data: [
            {
              id:
                options.vendor === "codex"
                  ? "gpt-6.1-sol"
                  : "claude-sonnet-4-6",
              type: "model",
              display_name: "audit",
            },
          ],
          has_more: false,
        });
      if (
        !url.pathname.includes("responses") &&
        !url.pathname.includes("messages")
      )
        return Response.json({ ok: true });
      if (options.vendor === "claude" && body.stream !== true)
        return Response.json({
          id: "msg_validation",
          type: "message",
          role: "assistant",
          content: [{ type: "text", text: "ok" }],
          model: body.model,
          stop_reason: "end_turn",
          stop_sequence: null,
          usage: { input_tokens: 1, output_tokens: 1 },
        });
      const count = modelCalls++;
      if (options.scenario === "capacity")
        return Response.json(
          options.vendor === "claude"
            ? {
                type: "error",
                error: {
                  type: "overloaded_error",
                  message: "audit injected overload",
                },
              }
            : {
                error: {
                  type: "server_error",
                  code: "model_capacity_exceeded",
                  message:
                    "Selected model is at capacity. Please try a different model.",
                },
              },
          {
            status: options.vendor === "claude" ? 529 : 503,
            headers: { "retry-after": "0", "request-id": "audit-capacity" },
          },
        );
      if (options.scenario === "auth")
        return Response.json(
          {
            type: "error",
            error: {
              type: "authentication_error",
              message: "audit invalid credential",
            },
          },
          { status: 401 },
        );
      if (options.scenario === "stall")
        return new Response(
          new ReadableStream({
            start(controller) {
              controller.enqueue(
                new TextEncoder().encode(": audit keepalive\n\n"),
              );
            },
          }),
          { headers: { "content-type": "text/event-stream" } },
        );
      const tool =
        count === 0 &&
        ["tool", "sandbox", "hook-deny", "read-only"].includes(
          options.scenario,
        );
      if (options.vendor === "claude") {
        const available = body.tools ?? [];
        const selected =
          available.find((t) => t.name === "Bash") ??
          available.find((t) => /bash|terminal/i.test(t.name));
        const wantsTool = tool && selected !== undefined;
        const content = wantsTool
          ? {
              type: "tool_use",
              id: "toolu_audit_1",
              name: selected.name,
              input: {},
            }
          : { type: "text", text: "" };
        return sse([
          {
            event: "message_start",
            data: {
              type: "message_start",
              message: {
                id: `msg_audit_${count}`,
                type: "message",
                role: "assistant",
                content: [],
                model: body.model,
                stop_reason: null,
                stop_sequence: null,
                usage: { input_tokens: 20, output_tokens: 0 },
              },
            },
          },
          {
            event: "content_block_start",
            data: {
              type: "content_block_start",
              index: 0,
              content_block: content,
            },
          },
          {
            event: "content_block_delta",
            data: {
              type: "content_block_delta",
              index: 0,
              delta: wantsTool
                ? {
                    type: "input_json_delta",
                    partial_json: JSON.stringify({
                      command: options.command,
                      timeout: 5000,
                      description: "audit scoped filesystem check",
                    }),
                  }
                : {
                    type: "text_delta",
                    text:
                      options.scenario === "quote"
                        ? "Selected model is at capacity. overloaded_error is quoted fixture text."
                        : "AUDIT_COMPLETED",
                  },
            },
          },
          {
            event: "content_block_stop",
            data: { type: "content_block_stop", index: 0 },
          },
          {
            event: "message_delta",
            data: {
              type: "message_delta",
              delta: {
                stop_reason: wantsTool ? "tool_use" : "end_turn",
                stop_sequence: null,
              },
              usage: { output_tokens: 5 },
            },
          },
          { event: "message_stop", data: { type: "message_stop" } },
        ]);
      }
      const tools =
        body.tools ??
        (body.input ?? [])
          .filter((x) => x.type === "additional_tools")
          .flatMap((x) => x.tools ?? []);
      const namespace = tools.find(
        (t) =>
          t.type === "namespace" && t.tools?.some((q) => q.name === "exec"),
      );
      const selected =
        tools.find((t) => t.name === "exec_command") ??
        tools.find((t) => t.name === "shell_command") ??
        tools.find((t) => t.name === "shell");
      const wantsTool =
        tool && (selected !== undefined || namespace !== undefined);
      let args: unknown = { command: options.command, timeout_ms: 5000 };
      if (selected?.name === "exec_command")
        args = {
          cmd: options.command,
          yield_time_ms: 1000,
          max_output_tokens: 1000,
        };
      if (selected?.name === "shell")
        args = {
          command: ["/bin/sh", "-c", options.command],
          timeout_ms: 5000,
        };
      const customItem = {
        type: "custom_tool_call",
        id: `ct_audit_${count}`,
        call_id: `call_audit_${count}`,
        name: "exec",
        namespace: namespace?.name,
        input: `const result = await tools.exec_command(${JSON.stringify({ cmd: options.command, shell: "/bin/sh", login: false, max_output_tokens: 1000 })}); text(result);`,
        status: "completed",
      };
      const item = wantsTool
        ? namespace !== undefined
          ? customItem
          : {
              type: "function_call",
              id: `fc_audit_${count}`,
              call_id: `call_audit_${count}`,
              name: selected.name,
              arguments: JSON.stringify(args),
              status: "completed",
            }
        : {
            type: "message",
            id: `msg_audit_${count}`,
            role: "assistant",
            status: "completed",
            content: [
              {
                type: "output_text",
                text:
                  options.scenario === "quote"
                    ? "Selected model is at capacity. overloaded_error is quoted fixture text."
                    : "AUDIT_COMPLETED",
                annotations: [],
              },
            ],
          };
      const response = {
        id: `resp_audit_${count}`,
        object: "response",
        created_at: 1770000000,
        model: body.model,
        status: "completed",
        output: [item],
        usage: {
          input_tokens: 20,
          output_tokens: 5,
          total_tokens: 25,
          input_tokens_details: { cached_tokens: 0 },
          output_tokens_details: { reasoning_tokens: 0 },
        },
      };
      return sse([
        {
          event: "response.created",
          data: {
            type: "response.created",
            response: { ...response, status: "in_progress", output: [] },
          },
        },
        {
          event: "response.output_item.added",
          data: {
            type: "response.output_item.added",
            output_index: 0,
            item: wantsTool ? item : { ...item, content: [] },
          },
        },
        ...(!wantsTool
          ? [
              {
                event: "response.content_part.added",
                data: {
                  type: "response.content_part.added",
                  item_id: item.id,
                  output_index: 0,
                  content_index: 0,
                  part: { type: "output_text", text: "", annotations: [] },
                },
              },
              {
                event: "response.output_text.delta",
                data: {
                  type: "response.output_text.delta",
                  item_id: item.id,
                  output_index: 0,
                  content_index: 0,
                  delta: item.content[0].text,
                },
              },
              {
                event: "response.output_text.done",
                data: {
                  type: "response.output_text.done",
                  item_id: item.id,
                  output_index: 0,
                  content_index: 0,
                  text: item.content[0].text,
                },
              },
            ]
          : []),
        {
          event: "response.output_item.done",
          data: { type: "response.output_item.done", output_index: 0, item },
        },
        {
          event: "response.completed",
          data: { type: "response.completed", response },
        },
      ]);
    },
  });
  return {
    server,
    url: `http://127.0.0.1:${server.port}`,
    counts: () => ({ requests, modelCalls }),
  };
}

