import { appendFileSync } from "node:fs";

const log = process.env.AGX_AUDIT_HOOK_LOG;
if (log === undefined || !log.startsWith("/tmp/agx-native-"))
  throw Error("invalid audit hook log");
const text = await Bun.stdin.text();
const payload: unknown = JSON.parse(text);
appendFileSync(log, `${JSON.stringify(payload)}\n`);
if (text.includes("audit-hook-denied") && text.includes("PreToolUse")) {
  process.stdout.write(
    `${JSON.stringify({ hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: "audit native hook denied this command" } })}\n`,
  );
} else if (text.includes("SessionStart") || text.includes("UserPromptSubmit")) {
  const event = text.includes("UserPromptSubmit")
    ? "UserPromptSubmit"
    : "SessionStart";
  process.stdout.write(
    `${JSON.stringify({ hookSpecificOutput: { hookEventName: event, additionalContext: "AUDIT_NATIVE_HOOK_CONTEXT" } })}\n`,
  );
}

