// Test fixture: launch the real vendor binary with this run's isolated provider/configuration.
// argv-forwarding: native-vendor-cli
import { typeFlag } from "type-flag";
const argv = process.argv.slice(2);
const boundary = typeFlag({}, argv.slice(), {
  ignore: (type, flag) => {
    if (type === "unknown-flag" && flag === "__proto__")
      throw Error("invalid prototype flag");
  },
});
if (Object.hasOwn(boundary.unknownFlags, "__proto__"))
  throw Error("invalid prototype flag");
const path = process.env.AGX_AUDIT_NATIVE_ENV_FILE;
if (path === undefined || !path.startsWith("/tmp/agx-native-"))
  throw Error("missing fixture environment");
const env = await Bun.file(path).json();
