#!/usr/bin/env bun
// Test fixture: forward the installed Codex app-server and observe its native hook configuration.
import { createInterface } from "node:readline";
import { appendFileSync } from "node:fs";
import { join } from "node:path";
const child = Bun.spawn(
  [
    "/home/linuxbrew/.linuxbrew/bin/codex",
    "--dangerously-bypass-hook-trust",
    "app-server",
  ],
  { stdin: "pipe", stdout: "pipe", stderr: "inherit", timeout: 25000 },
);
const log = process.env.AGX_AUDIT_HOOK_LOG;
const object = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;
let pendingStart: Record<string, unknown> | undefined;
process.on("SIGTERM", () => child.kill("SIGTERM"));
process.on("SIGINT", () => child.kill("SIGINT"));
const input = createInterface({ input: process.stdin });
input.on("line", (line) => {
  let value: unknown;
  try {
    value = JSON.parse(line);
  } catch {
    child.stdin.write(`${line}\n`);
    return;
  }
  if (log !== undefined && object(value))
    appendFileSync(
      `${log}.wire`,
      `${JSON.stringify({ method: value.method, keys: object(value.params) ? Object.keys(value.params) : [] })}\n`,
    );
  if (
    object(value) &&
    value.method === "thread/start" &&
    object(value.params) &&
    process.env.AGX_AUDIT_PATCH_HOOK_SOURCE === "1"
  )
    value.params.sessionStartSource = "startup";
  if (
    object(value) &&
    value.method === "thread/start" &&
    process.env.AGX_AUDIT_TRUST_HOOKS === "1"
  ) {
    pendingStart = value;
    child.stdin.write(
      `${JSON.stringify({ id: "audit-hooks-trust", method: "hooks/list", params: { cwds: [process.cwd()] } })}\n`,
    );
    return;
  }
  child.stdin.write(`${JSON.stringify(value)}\n`);
  if (object(value) && value.method === "thread/start")
    child.stdin.write(
      `${JSON.stringify({ id: "audit-hooks-list", method: "hooks/list", params: { cwds: [process.cwd()] } })}\n`,
    );
  if (object(value) && value.method === "initialized")
    child.stdin.write(
      `${JSON.stringify({ id: "audit-hooks-list", method: "hooks/list", params: { cwds: [process.cwd()] } })}\n`,
    );
});
input.on("close", () => child.stdin.end());
const reader = (async () => {
  let pending = "";
  for await (const chunk of child.stdout) {
    pending += new TextDecoder().decode(chunk);
    let end = pending.indexOf("\n");
    while (end >= 0) {
      const line = pending.slice(0, end);
      pending = pending.slice(end + 1);
      let value: unknown;
      try {
        value = JSON.parse(line);
      } catch {
        process.stdout.write(`${line}\n`);
        end = pending.indexOf("\n");
        continue;
      }
      if (
        object(value) &&
        value.id === "audit-hooks-trust" &&
        object(value.result) &&
        Array.isArray(value.result.data)
      ) {
        const home = process.env.CODEX_HOME;
        if (home === undefined || !home.startsWith("/tmp/agx-native-"))
          throw Error("fixture trust requires isolated config home");
        for (const row of value.result.data.filter(object)) {
          if (!Array.isArray(row.hooks)) continue;
          for (const hook of row.hooks.filter(object)) {
            if (
              typeof hook.key !== "string" ||
              typeof hook.currentHash !== "string" ||
              hook.sourcePath !== join(home, "hooks.json")
            )
              continue;
            appendFileSync(
              join(home, "config.toml"),
              `\n[hooks.state.${JSON.stringify(hook.key)}]\nenabled = true\ntrusted_hash = ${JSON.stringify(hook.currentHash)}\n`,
            );
          }
        }
        if (pendingStart === undefined) throw Error("missing pending start");
        child.stdin.write(`${JSON.stringify(pendingStart)}\n`);
        pendingStart = undefined;
        child.stdin.write(
          `${JSON.stringify({ id: "audit-hooks-list", method: "hooks/list", params: { cwds: [process.cwd()] } })}\n`,
        );
      } else if (object(value) && value.id === "audit-hooks-list") {
        if (log !== undefined)
          appendFileSync(`${log}.configuration`, `${JSON.stringify(value)}\n`);
      } else process.stdout.write(`${line}\n`);
      end = pending.indexOf("\n");
    }
  }
  if (pending !== "") process.stdout.write(pending);
})();
const code = await child.exited;
input.close();
await reader;
process.exitCode = code;

