import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { createAcpRuntime, createAgentRegistry, createFileSessionStore } from "/tmp/agx-decision-0E6raB/acpx-package/dist/runtime.js";
import { runAcpxWorker } from "./acpx-worker-candidate.ts";

// Native Node fixture for the published package's supported runtime; Bun owns the HTTP test server.
async function main() {
  const path = process.env.AGX_AUDIT_NODE_INPUT;
  if (path === undefined || !path.startsWith("/tmp/agx-native-")) throw Error("missing native fixture input");
  const input = JSON.parse(await readFile(path, "utf8"));
  const runtime = createAcpRuntime({
    cwd: input.cwd,
    sessionStore: createFileSessionStore({ stateDir: join(input.root, "node-state") }),
    agentRegistry: createAgentRegistry({ overrides: { [input.vendor]: [process.execPath, join(import.meta.dirname, input.adapter, "dist/index.js")] } }),
    agentProcessEnv: input.env,
    permissionMode: "deny-all", fs: false, terminal: false, timeoutMs: 15000,
  });
  const events: unknown[] = [];
  try {
    const receipt = await runAcpxWorker({ runtime, input: { sessionKey: `node-${input.vendor}-${input.scenario}`, agent: input.vendor, mode: "persistent", sessionOptions: { model: input.vendor === "codex" ? "gpt-6.1-sol" : "claude-sonnet-4-6", maxTurns: 3 } }, vendor: input.vendor, prompt: "Perform the scoped audit task; reply AUDIT_COMPLETED.", sandbox: "workspace-write", timeoutMs: 15000, onEvent: event => events.push(event) });
    events.push({ type: "bridge_receipt", ...receipt });
    process.stdout.write(`${JSON.stringify({ node: process.version, events })}\n`);
  } finally { await runtime.shutdown(); }
}
main().catch(error => { process.stderr.write(`FATAL: ${String(error)}\n`); process.exitCode = 2; });

native-acceptance.test.ts.source:
import { test, expect } from "bun:test";
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const root = import.meta.dir;
const evidence: unknown[] = [];
async function run(transport: string, vendor: string, scenario: string) {
  const signal = AbortSignal.timeout(26000);
  // bounded: each native probe is aborted by its 26-second signal.
  const child = Bun.spawn([process.execPath, join(root, "probe.ts")], {
    env: {
      ...process.env,
      AGX_AUDIT_TRANSPORT: transport,
      AGX_AUDIT_VENDOR: vendor,
      AGX_AUDIT_SCENARIO: scenario,
      AGX_AUDIT_ADAPTER_DIR:
        vendor === "codex"
          ? (process.env.AGX_AUDIT_CODEX_ADAPTER ?? "codex-compatible")
          : (process.env.AGX_AUDIT_CLAUDE_ADAPTER ?? "claude"),
      ...(vendor === "codex" && transport === "bridge"
        ? { AGX_AUDIT_TRUST_HOOKS: "1", AGX_AUDIT_PATCH_HOOK_SOURCE: "0" }
        : {}),
    },
    stdin: "ignore",
    stdout: "pipe",
    stderr: "pipe",
    signal: signal,
  });
  const [out, err, exit] = await Promise.all([
    child.stdout.text(),
    child.stderr.text(),
    child.exited,
  ]);
  if (exit !== 0 || signal.aborted)
    throw Error(`probe failed ${exit}: ${err.slice(-1500)} ${out.slice(-500)}`);
  const locator = JSON.parse(out.trim().split("\n").at(-1)!);
  const result = JSON.parse(
    await readFile(join(locator.root, "result.json"), "utf8"),
  );
  const receipt =
    result.events.find(
      (e) => e.type === "bridge_receipt" || e.type === "agx_receipt",
    ) ?? result.events.at(-1);
  evidence.push({
    transport,
    vendor,
    scenario,
    root: result.root,
    present: result.present,
    hooks: result.hooks,
    elapsedMs: result.elapsedMs,
    modelCalls: result.modelCalls,
    failure: result.failure,
    receipt,
  });
  await writeFile(
    join(root, "acceptance-results.json"),
    JSON.stringify(evidence, null, 2),
  );
  return { ...result, receipt };
}
for (const vendor of ["codex", "claude"]) {
  test(`${vendor}: native hooks run and allowed commands execute through the replacement`, async () => {
    const r = await run("bridge", vendor, "tool");
    expect(r.failure).toBeUndefined();
    expect(r.present).toBe(true);
    for (const hook of [
      "SessionStart",
      "UserPromptSubmit",
      "PreToolUse",
      "PostToolUse",
      "Stop",
    ])
      expect(r.hooks).toContain(hook);
    expect(r.receipt.exit_code).toBe(0);
  }, 30000);
  test(`${vendor}: native PreToolUse denial prevents the actual write`, async () => {
    const r = await run("bridge", vendor, "hook-deny");
    expect(r.hooks).toContain("PreToolUse");
    expect(r.present).toBe(false);
  }, 30000);
  test(`${vendor}: workspace sandbox prevents writes outside the working tree`, async () => {
    const r = await run("bridge", vendor, "sandbox");
    expect(r.failure).toBeUndefined();
    expect(r.modelCalls).toBeGreaterThanOrEqual(2);
    expect(r.present).toBe(false);
  }, 30000);
  test(`${vendor}: read-only mode prevents writes inside the working tree`, async () => {
    const r = await run("bridge", vendor, "read-only");
    expect(r.failure).toBeUndefined();
    expect(r.modelCalls).toBeGreaterThanOrEqual(2);
    expect(r.present).toBe(false);
  }, 30000);
  test(`${vendor}: quoted capacity words remain ordinary assistant output`, async () => {
    const r = await run("bridge", vendor, "quote");
    expect(r.receipt.exit_code).toBe(0);
    expect(r.receipt.outcome).toBe("returned");
    expect(r.receipt.last_message).toContain(
      "overloaded_error is quoted fixture text",
    );
  }, 30000);
  test(`${vendor}: current agx stops a real native capacity response with exit 75`, async () => {
    const r = await run("agx", vendor, "capacity");
    expect(r.receipt.exit ?? r.receipt.agx_process_exit).toBe(75);
    expect(r.modelCalls).toBe(1);
  }, 30000);
  test(`${vendor}: replacement preserves typed capacity and stops before a second model attempt`, async () => {
    const r = await run("bridge", vendor, "capacity");
    expect(r.receipt.outcome).toBe("capacity");
    expect(r.receipt.exit_code).toBe(75);
    expect(r.modelCalls).toBe(1);
  }, 30000);
}

