    command: `${process.execPath} ${join("/tmp/agx-native-o49jN4", "hook.ts")}`,
    timeout: 5,
  };
  const hooks = Object.fromEntries(
    [
      "SessionStart",
      "UserPromptSubmit",
      "PreToolUse",
      "PostToolUse",
      "Stop",
    ].map((event) => [event, [{ hooks: [hook] }]]),
  );
  const provider = {
